CREATE TABLE IF NOT EXISTS community_posts (     id UUID PRIMARY KEY,     author_id UUID NOT NULL,     topic VARCHAR(80) NOT NULL,     content TEXT NOT NULL,     visibility VARCHAR(20) NOT NULL,     status VARCHAR(20) NOT NULL,     reaction_count BIGINT NOT NULL DEFAULT 0,     comment_count BIGINT NOT NULL DEFAULT 0,     share_count BIGINT NOT NULL DEFAULT 0,     created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,     updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,     CONSTRAINT chk_community_posts_visibility         CHECK (visibility IN ('PUBLIC', 'CONNECTIONS')),     CONSTRAINT chk_community_posts_status         CHECK (status IN ('PUBLISHED', 'REPORTED', 'HIDDEN')),     CONSTRAINT fk_community_posts_author         FOREIGN KEY (author_id) REFERENCES users (id) ON DELETE CASCADE );  CREATE TABLE IF NOT EXISTS community_post_media (     id UUID PRIMARY KEY,     post_id UUID NOT NULL,     media_type VARCHAR(20) NOT NULL,     url VARCHAR(1000) NOT NULL,     object_key VARCHAR(500) NOT NULL,     content_type VARCHAR(120) NOT NULL,     sort_order INTEGER NOT NULL DEFAULT 0,     CONSTRAINT chk_community_post_media_type         CHECK (media_type IN ('IMAGE', 'VIDEO')),     CONSTRAINT fk_community_post_media_post         FOREIGN KEY (post_id) REFERENCES community_posts (id) ON DELETE CASCADE );  CREATE TABLE IF NOT EXISTS community_comments (     id UUID PRIMARY KEY,     post_id UUID NOT NULL,     author_id UUID NOT NULL,     content VARCHAR(1000) NOT NULL,     created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,     CONSTRAINT fk_community_comments_post         FOREIGN KEY (post_id) REFERENCES community_posts (id) ON DELETE CASCADE,     CONSTRAINT fk_community_comments_author         FOREIGN KEY (author_id) REFERENCES users (id) ON DELETE CASCADE );  CREATE TABLE IF NOT EXISTS community_reactions (     id UUID PRIMARY KEY,     post_id UUID NOT NULL,     user_id UUID NOT NULL,     reaction_type VARCHAR(20) NOT NULL,     CONSTRAINT chk_community_reactions_type         CHECK (reaction_type IN ('LIKE', 'LOVE', 'WOW', 'CARE')),     CONSTRAINT uq_community_reactions_post_user         UNIQUE (post_id, user_id),     CONSTRAINT fk_community_reactions_post         FOREIGN KEY (post_id) REFERENCES community_posts (id) ON DELETE CASCADE,     CONSTRAINT fk_community_reactions_user         FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE );  CREATE INDEX IF NOT EXISTS idx_community_posts_feed     ON community_posts (status, created_at DESC);  CREATE INDEX IF NOT EXISTS idx_community_posts_author     ON community_posts (author_id, created_at DESC);  CREATE INDEX IF NOT EXISTS idx_community_post_media_post     ON community_post_media (post_id, sort_order ASC);  CREATE INDEX IF NOT EXISTS idx_community_comments_post     ON community_comments (post_id, created_at ASC);